const client = new OpenAI(); // reads OPENAI_API_KEY from the environment

// Model-specific settings are reviewed configuration, changed one hypothesis at a time.
// Current guidance for the flagship model: https://developers.openai.com/api/docs/guides/latest-model
const config = {
  model: process.env.OPENAI_MODEL, // verify current ids: https://developers.openai.com/api/docs/models
  reasoningEffort: (process.env.OPENAI_REASONING_EFFORT ?? "low") as "low" | "medium" | "high",
  promptVersion: "ticket-triage@4",
};
if (!config.model) throw new Error("OPENAI_MODEL is not configured");

const response = await client.responses.create({
  model: config.model,
  reasoning: { effort: config.reasoningEffort },
  // No temperature or top_p: current flagship migration guidance says to remove them.
  // Re-check that guidance whenever OPENAI_MODEL changes.
  instructions: triageInstructions,
  input: ticketText,
});

await recordRun({ ...config, status: response.status, usage: response.usage }); // baseline kept for rollback

// Baseline and candidate run on identical cases and configuration; only the prompt version differs.
type MissCategory =
  | "instruction-ambiguity"
  | "missing-context"
  | "misleading-example"
  | "output-violation"
  | "model-limitation"
  | "tool-failure"
  | "policy-boundary"
  | "application-defect";

interface RunRecord {
  promptVersion: string;
  model: string;
  caseId: string;
  rubricPass: boolean;
  critical: boolean;
  latencyMs: number;
  outputTokens: number;
  miss?: MissCategory; // assigned by a reviewer for every failed case
}

function decide(baseline: RunRecord[], candidate: RunRecord[]) {
  const passRate = (runs: RunRecord[]) => runs.filter((r) => r.rubricPass).length / runs.length;
  const baselineCritical = new Set(baseline.filter((r) => r.critical).map((r) => r.caseId));
  const newCritical = candidate.filter((r) => r.critical && !baselineCritical.has(r.caseId));
  const keep = baseline[0].promptVersion;

  if (newCritical.length) return { promote: false, keep, reason: "new critical failures", cases: newCritical.map((r) => r.caseId) };
  if (passRate(candidate) <= passRate(baseline)) return { promote: false, keep, reason: "no measured gain" };
  return { promote: true, rollbackTo: keep }; // repaired misses join the regression set
}
